1	//! Direct local-binding lookup for build-time receiver typing.
2	//!
3	//! This intentionally returns the original [`Binding`] rather than the engine's
4	//! [`Candidate`](crate::name_resolution::types::Candidate), because the
5	//! Task-2.3 receiver typer needs the binding span as a def-byte identity.
6	
7	use crate::name_resolution::graph::ScopeGraph;
8	use crate::name_resolution::rust_policy::{EK_GLOB, NS_VALUE};
9	use crate::name_resolution::rust_populator::enclosing_scope;
10	use crate::name_resolution::types::{BindTarget, Binding, FileId, ScopeKind, SourceLoc, Target};
11	use serde::{Deserialize, Serialize};
12	
13	/// Syntactic kind of a Rust local binding.
14	#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
15	pub enum BindingKind {
16	    Param,
17	    Let,
18	    Pattern,
19	}
