89	/// Resolve a `crate::`-anchored path's final `(name, ns)` from the crate root.
90	fn resolve_crate_path(
91	    g: &ScopeGraph,
92	    fs: &BTreeMap<String, ParsedFile>,
93	    edition: u16,
94	    root_path: &str,
95	    segs: &[&str],
96	    ns: NamespaceId,
97	) -> Resolution {
98	    let fid = file_id(fs, root_path).expect("file id");
